71: macro_rules! blocking_fn {
72:     ($self:ident, $fn:ident) => {{
73:         let (tx, rx) = sync_channel(0);
74:         let cb = move |response| {
75:             tx.send(response).unwrap();
76:         };
77:         $self.$fn(cb);
78:         rx.recv().unwrap()
79:     }};
80: }
