230:                     rfd::MessageDialogResult::Custom(s)
231:                 }
232:                 (
233:                     rfd::MessageDialogResult::Ok,
234:                     MessageDialogButtons::OkCancelCustom(ok, _cancel),
235:                 ) => rfd::MessageDialogResult::Custom(ok),
236:                 (
237:                     rfd::MessageDialogResult::Cancel,
