239:                 ) => rfd::MessageDialogResult::Custom(cancel),
240:                 (
241:                     rfd::MessageDialogResult::Yes,
242:                     MessageDialogButtons::YesNoCancelCustom(yes, _no, _cancel),
243:                 ) => rfd::MessageDialogResult::Custom(yes),
244:                 (
