247:                 ) => rfd::MessageDialogResult::Custom(no),
248:                 (
249:                     rfd::MessageDialogResult::Cancel,
250:                     MessageDialogButtons::YesNoCancelCustom(_yes, _no, cancel),
251:                 ) => rfd::MessageDialogResult::Custom(cancel),
252:                 (result, _) => result,
253:             };
254:             f(result);
255:         });
256:     });
